package dev.modaal.foyer.theming

import dev.modaal.duet.services.theming.ColorToken
import dev.modaal.duet.services.theming.FontFamilyToken
import dev.modaal.duet.services.theming.FontToken

/**
 * The values behind the vocabularies — one entry per token, in the terms the
 * engine reads.
 *
 * Colours and gradient stops are `0xAARRGGBB`. Each `when` is exhaustive over
 * its vocabulary, so a token added to the config gets a value in the same
 * generation.
 */
object MainPalette {

  fun color(token: SemanticColor): ColorToken =
    when (token) {

      // Surfaces
      SemanticColor.surface -> ColorToken.auto(light = 0xFFFFFFFF, dark = 0xFF121212)
      SemanticColor.cardSurface -> ColorToken.auto(light = 0xFFF1F1EE, dark = 0xFF262626)
      // A warm wash rather than a grey: the locked state is a state of the
      // card, and a colour the eye reads before the lock glyph does.
      SemanticColor.lockedSurface -> ColorToken.auto(light = 0xFFFBF3DC, dark = 0xFF3B3320)

      // Labels
      SemanticColor.labelPrimary -> ColorToken.auto(light = 0xFF1A1A1A, dark = 0xFFEDEDED)
      SemanticColor.labelSecondary -> ColorToken.auto(light = 0xFF6A6A6A, dark = 0xFF9C9C9C)
      SemanticColor.labelLocked -> ColorToken.auto(light = 0xFF7A5C0A, dark = 0xFFE5C15C)

      // Chrome
      // Translucent, so it reads as a tint of whichever surface the card sits
      // on; the high-contrast theme maps it onto the primary label, which makes
      // it a solid line of ink.
      SemanticColor.cardBorder -> ColorToken.auto(light = 0x1F1A1A1A, dark = 0x29EDEDED)
    }

  fun font(token: SemanticFont): FontToken =
    when (token) {

      // The two card styles
      SemanticFont.cardTitle ->
        FontToken(
          family = FontFamilyToken.Sans,
          weight = 600,
          sizeSp = 17.0,
          lineHeightSp = 22.0,
          trackingEm = 0.0,
          opticalSize = null,
          softness = null,
          width = null,
        )
      SemanticFont.cardBody ->
        FontToken(
          family = FontFamilyToken.Sans,
          weight = 400,
          sizeSp = 15.0,
          lineHeightSp = 20.0,
          trackingEm = 0.0,
          opticalSize = null,
          softness = null,
          width = null,
        )
    }
}
